export const seedBlocks = async () => {
    try {
        await Block.deleteMany({});
        const states = await State.find({});

        if (!states.length) {
            console.log("No states found ❌");
            process.exit(1);
        }

        let inserted = 0;
        let skipped = 0;

        for (const state of states) {
            // Find state from blocks data
            const stateData = blocks.find(
                (item) => item.state === state.name
            );

            if (!stateData) {
                console.log(
                    `State data not found: ${state.name} ⚠️`
                );
                continue;
            }

            // Get districts for this state
            const districts = await District.find({
                stateId: state._id,
            });

            for (const district of districts) {
                // Find district inside current state
                const districtData = stateData.districts.find(
                    (item) => item.name === district.name
                );

                if (!districtData) {
                    console.log(
                        `District data not found: ${district.name} ⚠️`
                    );
                    continue;
                }

                // Create blocks
                for (const blockName of districtData.blocks) {
                    const exists = await Block.findOne({
                        stateId: state._id,
                        districtId: district._id,
                        name: blockName,
                    });

                    if (exists) {
                        skipped++;
                        continue;
                    }

                    await Block.create({
                        name: blockName,
                        stateId: state._id,
                        districtId: district._id,
                        isActive: true,
                    });

                    inserted++;
                }
            }
        }

        console.log("--------------------------------");
        console.log(`Blocks inserted: ${inserted} ✅`);
        console.log(`Blocks skipped: ${skipped} ⏭️`);
        console.log("--------------------------------");

        process.exit(0);
    } catch (error) {
        console.error("Block seed error ❌", error);
        process.exit(1);
    }
};